create table access_metrics (id int8 generated by default as identity, additional_data varchar(255), created_at timestamp not null, event_type varchar(255) not null, ip_address varchar(255), session_id varchar(255), user_agent varchar(255), primary key (id));
create table account (id int8 generated by default as identity, cep varchar(255), city varchar(255), company_name varchar(255), country varchar(255), cpf varchar(255), creci varchar(255), custom_domain varchar(255), domain varchar(255), email varchar(255), end_date varchar(255), is_trial_active boolean, last_name varchar(255), logo varchar(255), neighborhood varchar(255), netlify_site_id varchar(255), netlify_token varchar(255), number varchar(255), office_name varchar(255), password varchar(255), phone varchar(255), plan_end_date timestamp, plan_start_date timestamp, plan_type int4, proprietario varchar(255), renovation varchar(255), slug varchar(255), start varchar(255), state varchar(255), status int4, street varchar(255), verification int4, primary key (id));
create table address (id int8 generated by default as identity, zone varchar(255), cep varchar(255), complement varchar(255), district varchar(255), number varchar(255), street varchar(255), account_id int8, city_id int8, property_id int8, primary key (id));
create table city (id int8 generated by default as identity, name varchar(255), state_id int8, primary key (id));
create table features (property_id int8 not null, features int4);
create table image (id int8 generated by default as identity, id_account int8, url TEXT, property_id int8, primary key (id));
create table lead (id int8 generated by default as identity, email varchar(255), instant varchar(255), message varchar(255), name varchar(255), phone varchar(255), property_id int8, account_id int8, primary key (id));
create table notifications (id int8 generated by default as identity, created_at timestamp not null, is_read boolean not null, message varchar(255) not null, read_at timestamp, reference_user_email varchar(255), reference_user_id int8, reference_user_name varchar(255), title varchar(255) not null, type varchar(255) not null, primary key (id));
create table opportunity (id int8 generated by default as identity, instant varchar(255), property_id int8, account_id int8, lead_id int8, step_id int8, primary key (id));
create table perfis (tenant_id int8 not null, perfis int4);
create table property (id int8 generated by default as identity, area varchar(255), area_total varchar(255), bath_rooms varchar(255), buildings varchar(255), condominium varchar(255), construction_status varchar(255), description text, financeable varchar(255), floors varchar(255), gated_condominium varchar(255), goal int4, iptu varchar(255), name varchar(255), number_rooms varchar(255), permuta varchar(255), price varchar(255), property_administration_fee varchar(255), publication_type varchar(255), rentalprice varchar(255), status_featured int4, status_property int4, suites varchar(255), type_description varchar(255), type_property int4, unit_floor varchar(255), vacancies varchar(255), account_id int8, primary key (id));
create table state (id int8 generated by default as identity, name varchar(255), primary key (id));
create table step (id int8 generated by default as identity, name varchar(15), account_id int8, primary key (id));
create table stripe_customers (id int8 generated by default as identity, created_at timestamp, email varchar(255), name varchar(255), stripe_customer_id varchar(255) not null, updated_at timestamp, account_id int8 not null, primary key (id));
create table stripe_subscriptions (id int8 generated by default as identity, amount numeric(19, 2), created_at timestamp, currency varchar(255), current_period_end timestamp, current_period_start timestamp, plan_type varchar(255), status varchar(255), stripe_price_id varchar(255), stripe_subscription_id varchar(255) not null, updated_at timestamp, stripe_customer_id int8 not null, primary key (id));
create table tenant (id int8 generated by default as identity, cep varchar(255), city varchar(255), country varchar(255), cpf varchar(255), creci varchar(255), custom_domain varchar(255), domain varchar(255), email varchar(255), end_date varchar(255), last_name varchar(255), neighborhood varchar(255), number varchar(255), office_name varchar(255), password varchar(255), phone varchar(255), plain_password varchar(255), proprietario varchar(255), renovation varchar(255), slug varchar(255), start varchar(255), state varchar(255), status int4, street varchar(255), verification int4, account_id int8, primary key (id));
create table theme (id int8 generated by default as identity, about_us TEXT, agent_name varchar(255), agent_photo varchar(255), agent_quote varchar(255), banner_color varchar(255), banner_image varchar(255), banner_title varchar(255), banner_title_color varchar(255), banner_title_size int4, button_color varchar(255), contact_image varchar(255), contact_title varchar(255), custom_domain varchar(255), facebook_pixel varchar(255), favicon varchar(255), footer_background_color varchar(255), footer_logo varchar(255), footer_text varchar(255), h2color varchar(255), h3color varchar(255), logo varchar(255), logo_size varchar(255), main_color varchar(255), menu_links TEXT, name varchar(255), phone varchar(255), privacy_policy TEXT, seo_keywords TEXT, services TEXT, site_title varchar(255), social_links TEXT, text_color varchar(255), tenant_id int8, primary key (id));
create table urls (id int8 generated by default as identity, id_account int8, url TEXT, property_id int8, primary key (id));
create table user_admin_perfis (user_admin_id int8 not null, perfis int4);
create table user_admin (id int8 generated by default as identity, creci varchar(255), email varchar(255), end_date varchar(255), last_name varchar(255), password varchar(255), slug varchar(255), start varchar(255), status int4, verification int4, primary key (id));
create table warranties (property_id int8 not null, warranties int4);
